(args, got, expected) => {
    const [a, b] = args;
    if (!Array.isArray(got) || got.length !== expected.length) return false;
    const ca = new Map(), cb = new Map(), used = new Map();
    for (const x of a) ca.set(x, (ca.get(x) || 0) + 1);
    for (const y of b) cb.set(y, (cb.get(y) || 0) + 1);
    let prev = -Infinity;
    for (const p of got) {
      if (!Array.isArray(p) || p.length !== 2) return false;
      const s = p[0] + p[1];
      if (s < prev) return false;
      prev = s;
      const key = p[0] + "," + p[1];
      const u = (used.get(key) || 0) + 1;
      used.set(key, u);
      if (u > (ca.get(p[0]) || 0) * (cb.get(p[1]) || 0)) return false;
    }
    const es = expected.map(p => p[0] + p[1]).sort((x, y) => x - y);
    return got.every((p, i) => p[0] + p[1] === es[i]);
  }

