function lightestPairs(a: number[], b: number[], k: number): number[][] {
  const all: number[][] = [];
  for (const x of a) for (const y of b) all.push([x, y]);
  all.sort((p, q) => p[0] + p[1] - (q[0] + q[1]));
  return all.slice(0, k);
}

