class MinHeap {
  private h: number[][] = [];
  get size(): number { return this.h.length; }
  push(x: number[]): void {
    const h = this.h;
    h.push(x);
    let i = h.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (h[p][0] <= h[i][0]) break;
      [h[p], h[i]] = [h[i], h[p]];
      i = p;
    }
  }
  pop(): number[] {
    const h = this.h, top = h[0], last = h.pop()!;
    if (h.length) {
      h[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < h.length && h[l][0] < h[m][0]) m = l;
        if (r < h.length && h[r][0] < h[m][0]) m = r;
        if (m === i) break;
        [h[m], h[i]] = [h[i], h[m]];
        i = m;
      }
    }
    return top;
  }
}

function lightestPairs(a: number[], b: number[], k: number): number[][] {
  const heap = new MinHeap();
  for (let i = 0; i < Math.min(k, a.length); i++) heap.push([a[i] + b[0], i, 0]);
  const out: number[][] = [];
  while (out.length < k && heap.size) {
    const [, i, j] = heap.pop();
    out.push([a[i], b[j]]);
    if (j + 1 < b.length) heap.push([a[i] + b[j + 1], i, j + 1]);
  }
  return out;
}

