class Solution:
    def lightestPairs(self, a: List[int], b: List[int], k: int) -> List[List[int]]:
        heap = [(a[i] + b[0], i, 0) for i in range(min(k, len(a)))]
        heapq.heapify(heap)
        out = []
        while len(out) < k and heap:
            _, i, j = heapq.heappop(heap)
            out.append([a[i], b[j]])
            if j + 1 < len(b):
                heapq.heappush(heap, (a[i] + b[j + 1], i, j + 1))
        return out

